        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            modelBuilder.Entity<AccessLevel>(entity =>
            {
                entity.ToTable("AccessLevel", "base");

                entity.HasAnnotation("Relational:Comment", "سطح دسترسی");

                entity.HasIndex(e => e.CreateBy, "IX_AccessLevel_CreateBy_dynamic")
                    .HasFillFactor(90);

                entity.HasIndex(e => e.ModifyBy, "IX_AccessLevel_ModifyBy_dynamic")
                    .HasFillFactor(90);

                entity.Property(e => e.Id).HasComment("کد");

                entity.Property(e => e.CreateBy).HasComment("ایجاد کننده");

                entity.Property(e => e.CreationDate)
                    .HasColumnType("datetime")
                    .HasComment("زمان ایجاد");

                entity.Property(e => e.Deleted)
                    .HasDefaultValue(false)
                    .HasComment("حذف شده");

                entity.Property(e => e.Description).HasComment("توضیح");

                entity.Property(e => e.LevelValue).HasComment("مقدار سطح دسترسی");

                entity.Property(e => e.ModificationDate)
                    .HasColumnType("datetime")
                    .HasComment("زمان تغییر");

                entity.Property(e => e.ModifyBy).HasComment("ویرایش کننده");

                entity.Property(e => e.Title)
                    .IsRequired()
                    .HasMaxLength(150)
                    .HasComment("عنوان");

                entity.HasOne(d => d.CreateByNavigation)
                    .WithMany(p => p.AccessLevelCreateByNavigation)
                    .HasForeignKey(d => d.CreateBy)
                    .OnDelete(DeleteBehavior.ClientSetNull)
                    .HasConstraintName("FK_AccessLevel_User");

                entity.HasOne(d => d.ModifyByNavigation)
                    .WithMany(p => p.AccessLevelModifyByNavigation)
                    .HasForeignKey(d => d.ModifyBy)
                    .HasConstraintName("FK_AccessLevel_User1");
            });

            modelBuilder.Entity<ActiveStorageAttachment>(entity =>
            {
                entity.ToTable("ActiveStorageAttachment", "yl");

                entity.HasAnnotation("Relational:Comment", "پیوست ذخیره سازی فعال");

                entity.Property(e => e.Id).HasComment("شناسه پیوست");

                entity.Property(e => e.AccessLevelId).HasComment("سطح دسترسی");

                entity.Property(e => e.ApplicationId).HasComment("برنامه");

                entity.Property(e => e.BlobId).HasComment("شناسه وبینار");

                entity.Property(e => e.CreateBy).HasComment("ایجاد کننده");

                entity.Property(e => e.CreationDate)
                    .HasColumnType("datetime")
                    .HasComment("زمان ایجاد");

                entity.Property(e => e.Deleted)
                    .HasDefaultValue(false)
                    .HasComment("حذف شده");

                entity.Property(e => e.ModificationDate)
                    .HasColumnType("datetime")
                    .HasComment("زمان تغییر");

                entity.Property(e => e.ModifyBy).HasComment("ویرایش کننده");

                entity.Property(e => e.Name)
                    .IsRequired()
                    .HasMaxLength(300)
                    .HasComment("نام پیوست");

                entity.Property(e => e.RecordId).HasComment("شناسه ضبط");

                entity.Property(e => e.RecordType)
                    .IsRequired()
                    .HasMaxLength(300)
                    .HasComment("فرمت ضبط");

                entity.HasOne(d => d.AccessLevel)
                    .WithMany(p => p.ActiveStorageAttachment)
                    .HasForeignKey(d => d.AccessLevelId)
                    .OnDelete(DeleteBehavior.ClientSetNull)
                    .HasConstraintName("FK_ActiveStorageAttachment_AccessLevel");

                entity.HasOne(d => d.Application)
                    .WithMany(p => p.ActiveStorageAttachment)
                    .HasForeignKey(d => d.ApplicationId)
                    .OnDelete(DeleteBehavior.ClientSetNull)
